const ee = require('@google/earthengine');
const privateKey = require('./.earthsense-436113-b294c5f5c2dc.json');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const blueLagoonPoint = ee.Geometry.Point([-22.4527, 63.8810]); // [lon, lat]
  const reykjavikPoint = ee.Geometry.Point([-21.9426, 64.1466]); // [lon, lat]

  const bufferSize = 1000; // 1 km buffer around points
  const blueLagoon = blueLagoonPoint.buffer(bufferSize);
  const reykjavik = reykjavikPoint.buffer(bufferSize);

  // The question asks for November 24, 2024. This is a future date.
  // Earth Engine data does not exist for future dates.
  // We will attempt to filter, but expect an empty collection.
  const startDate = '2024-11-24';
  const endDate = '2024-11-25'; // End date is exclusive, so it includes Nov 24.

  // 2. Data Acquisition & Check
  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/VCMCFG/V1_TO_V2')
    .filterDate(startDate, endDate)
    .filterBounds(blueLagoon.union(reykjavik))
    .select(['avg_rad', 'cloud_mask']);

  const collectionSize = await viirsCollection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No data found for November 24, 2024.");
    console.log("Reason: The specified date is in the future, and Earth Engine does not contain future data.");
    console.log("C1");
    return;
  }

  // If for some reason data exists (e.g., test with an old date), proceed with processing.
  // This part of the code won't be reached for the given future date.
  // However, for completeness, here's how the processing would look.

  // Function to mask clouds in VIIRS DNB images
  const maskClouds = (image) => {
    const cloudMask = image.select('cloud_mask');
    // Clear (0) or Probable Clear (1) pixels are kept.
    // Probable Cloudy (2) or Cloudy (3) pixels are masked.
    const maskedImage = image.updateMask(cloudMask.lt(2));
    return maskedImage;
  };

  const processedCollection = viirsCollection.map(maskClouds);

  const blueLagoonBrightness = await processedCollection.filterBounds(blueLagoon)
    .reduce(ee.Reducer.mean())
    .get('avg_rad').getInfo();

  const reykjavikBrightness = await processedCollection.filterBounds(reykjavik)
    .reduce(ee.Reducer.mean())
    .get('avg_rad').getInfo();

  // 3. Processing & 4. Calculation (if data were available)
  // Since we already determined the collection is empty, this part is hypothetical for the given question.
  // For robustness, calculate pixel counts for C2.
  const blueLagoonCount = await processedCollection.filterBounds(blueLagoon)
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: blueLagoon,
      scale: 750, // VIIRS nominal resolution
      maxPixels: 1e9
    })
    .get('avg_rad')
    .getInfo();

  const reykjavikCount = await processedCollection.filterBounds(reykjavik)
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: reykjavik,
      scale: 750,
      maxPixels: 1e9
    })
    .get('avg_rad')
    .getInfo();

  if (blueLagoonCount === 0 || reykjavikCount === 0) {
    console.log(`Blue Lagoon valid pixels: ${blueLagoonCount}`);
    console.log(`Reykjavik valid pixels: ${reykjavikCount}`);
    console.log("No valid pixels remain after cloud masking or due to geometry/date constraints.");
    console.log("C2");
    return;
  }

  // 5. Validation & Final Answer
  if (blueLagoonBrightness === null || isNaN(blueLagoonBrightness) ||
      reykjavikBrightness === null || isNaN(reykjavikBrightness)) {
    console.log(`Blue Lagoon Brightness: ${blueLagoonBrightness}`);
    console.log(`Reykjavik Brightness: ${reykjavikBrightness}`);
    console.log("Calculation resulted in None or NaN.");
    console.log("C3");
    return;
  }

  console.log(`Blue Lagoon Brightness: ${blueLagoonBrightness.toFixed(4)} (Pixels: ${blueLagoonCount})`);
  console.log(`Reykjavik Brightness: ${reykjavikBrightness.toFixed(4)} (Pixels: ${reykjavikCount})`);

  if (blueLagoonBrightness > reykjavikBrightness) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
